function validate([gifts, k]) {
  if (gifts.length < 1 || gifts.length > 1000) return 'gifts needs 1 to 1000 piles.';
  if (gifts.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each pile holds 1 to 10^9 gifts.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is between 1 and 1000.';
  return null;
}

