function pickGifts(gifts, k) {
  const heap = [...gifts];
  const n = heap.length;

  const siftDown = (i) => {
    while (true) {
      const left = 2 * i + 1;
      const right = left + 1;
      let largest = i;
      if (left < n && heap[left] > heap[largest]) largest = left;
      if (right < n && heap[right] > heap[largest]) largest = right;
      if (largest === i) return;
      [heap[i], heap[largest]] = [heap[largest], heap[i]];
      i = largest;
    }
  };

  for (let i = (n >> 1) - 1; i >= 0; i--) {
    siftDown(i);
  }

  for (let second = 0; second < k; second++) {
    if (heap[0] === 1) break;
    heap[0] = Math.floor(Math.sqrt(heap[0]));
    siftDown(0);
  }

  let total = 0;
  for (const pile of heap) {
    total += pile;
  }
  return total;
}

