function pickGifts(gifts, k) {
  const piles = gifts.slice();
  for (let t = 0; t < k; t++) {
    let best = 0;
    for (let i = 1; i < piles.length; i++) if (piles[i] > piles[best]) best = i;
    let root = 0;
    while ((root + 1) * (root + 1) <= piles[best]) root++;
    piles[best] = root;
  }
  return piles.reduce((a, b) => a + b, 0);
}

