function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(800, 1000);
    const cap = rand() < 0.5 ? 1e9 : int(1, 1e6);
    return [Array.from({ length: n }, () => int(1, cap)), int(1, 1000)];
  }
  const n = int(1, 8);
  const gifts = Array.from({ length: n }, () => {
    const r = rand();
    if (r < 0.4) return int(1, 30);
    if (r < 0.7) return int(1, 40) ** 2;
    if (r < 0.85) return int(1, 2000);
    return int(1, 1e9);
  });
  // Mix small values, perfect squares and a few huge piles so ties and exact roots both occur.
  return [gifts, int(1, 12)];
}
